/* ===== 1. 隐藏头像且不占位（官方支持，心声仍可点击） ===== */
.msg-avatar-me-container { 
  display: none !important; 
}

/* ===== 2. 气泡整体等比例缩小与颜色设定 ===== */
:root {
  /* --- 气泡等比缩小（字号与内边距） --- */
  --bubble-me-font-size: 13px;       /* 默认通常为 15px，缩小到 13px */
  --bubble-them-font-size: 13px;
  --bubble-me-padding: 8px 12px;     /* 缩小内边距，让气泡看起来更紧凑 */
  --bubble-them-padding: 8px 12px;

  /* --- 我方气泡 (颜色与缩小后的圆角) --- */
  --bubble-me-bg: #F2F3F7;
  --bubble-me-color: #262626; 
  /* 配合缩小的气泡，把原本 20px 的圆角按比例缩到 16px，右下角保持 0px */
  --bubble-me-radius: 16px 16px 0px 16px;
  --bubble-me-radius-first: 16px 16px 0px 16px;
  --bubble-me-radius-mid: 16px 16px 0px 16px;
  --bubble-me-radius-last: 16px 16px 0px 16px;

  /* --- 对方气泡 (颜色与缩小后的圆角) --- */
  --bubble-them-bg: #BCF3F6;
  --bubble-them-color: #262626;
  /* 配合缩小的气泡，把原本 20px 的圆角按比例缩到 16px，左上角保持 0px */
  --bubble-them-radius: 0px 16px 16px 16px;
  --bubble-them-radius-first: 0px 16px 16px 16px;
  --bubble-them-radius-mid: 0px 16px 16px 16px;
  --bubble-them-radius-last: 0px 16px 16px 16px;
}
:root {
  /* ===== 1. 永远直接显示翻译，不需要点击 ===== */
  --translation-always-show: 1;

  /* ===== 2. 翻译区块去方块化，改为虚线分割 ===== */
  --translation-bg: transparent;         /* 去除原本的方块背景色 */
  --translation-radius: 0px;             /* 去除圆角 */
  --translation-shadow: none;            /* 去除阴影 */

  /* 上方加一条虚线（可以根据需要调整颜色和粗细） */
  --translation-separator: 1px dashed rgba(0, 0, 0, 0.25); 

  /* 调整间距：让左右和原文字对齐，上下留出呼吸感 */
  --translation-margin: 6px 0 0 0;       /* 虚线距离上方原文字的距离 */
  --translation-padding: 8px 0 0 0;      /* 翻译文字距离上方虚线的距离 */

  /* ===== 3. 翻译文字的美化（可选） ===== */
  --translation-text-color: inherit;     /* 翻译颜色默认跟随原文字 */
  --translation-opacity: 0.7;            /* 稍微降低翻译文字的透明度，用来区分原文和译文 */
  --translation-size: 12px;              /* 翻译字号（比气泡字号13px再小一点点） */
}
/* 如果翻译内容完全为空，则彻底隐藏该区块和虚线 */
.msg-translation-content:empty {
  display: none !important;
}
.msg-translation-wrapper:has(.msg-translation-content:empty) {
  display: none !important;
}
/* 1. 让包裹“气泡+状态”的容器成为定位基准，并允许内容溢出 */
.msg-me .msg-content-stack {
  position: relative !important;
  overflow: visible !important; 
}

/* 2. 将原本在下方的状态文字绝对定位到左侧外面 */
.msg-me .msg-status-custom {
  position: absolute !important;
  right: 100% !important;         /* 把文字挤到气泡容器的最左侧外 */
  bottom: 0px !important;         /* 垂直方向与气泡的底部对齐 */
  margin-right: 8px !important;   /* 文字与气泡之间的距离，可自行改大小 */
  margin-top: 0px !important;     /* 清除原本默认的上方间距 */
  margin-bottom: 2px !important;  /* 微调对齐高度，让它看着更居中或平齐 */
  white-space: nowrap !important; /* 强制时间和已读文字保持在同一行，不换行 */
  text-align: right !important;   /* 文字靠右贴紧气泡 */
}
/* ================================================= */
/* 聊天气泡上方的昵称显示（只有连续消息的第一条会显示） */
/* ================================================= */
/* 对方昵称 */
.msg-them.is-first .msg-content-stack::before,
.msg-them.is-single .msg-content-stack::before {
  content: "변백현 귀여워.";      /* <=== 请在这里修改【对方】的昵称 */
  display: block;
  font-size: 11px;
  color: #8e8e8e;
  margin-bottom: 4px;
  margin-left: 4px;      /* 左侧稍微留白 */
  text-align: left;      /* 对方名字靠左对齐 */
}
/* ================================================= */
/* 1. 顶栏昵称右侧加入装饰贴图 */
/* ================================================= */
.chat-header-title {
  position: relative !important;
  overflow: visible !important;
}
.chat-header-title::after {
  content: "";
  position: absolute;
  background-image: url('https://img.heliar.top/file/1778027526062_retouch_2026050607352285.png');
  background-repeat: no-repeat;
  background-size: contain; 
  pointer-events: none; /* 防止阻挡点击 */

  /* ▼▼▼▼▼ 调整大小和位置的地方 ▼▼▼▼▼ */
  width: 15px;            /* 【大小】修改这里调整图片的宽度 */
  height: 15px;           /* 【大小】修改这里调整图片的高度 */
  top: 50%;               /* 【上下位置】50%代表垂直居中，也可以改成具体的 px 比如 2px */
  transform: translateY(-50%); /* 配合 top: 50% 保证完美居中对齐文字 */
  right: -22px;           /* 【左右位置】负值表示往名字右侧外部移动，数字越大越靠右 */
}

/* ================================================= */
/* 2. 隐藏电话键（隐身但依然可以点击） */
/* ================================================= */
.header-btn-phone svg {
  opacity: 0 !important;  /* 把原图标设为完全透明，完美保留了按钮的点击功能 */
}

/* ================================================= */
/* 3. 视频与设置按钮替换贴图 */
/* ================================================= */

/* --- 视频按钮 --- */
.header-btn-video svg { display: none !important; } /* 隐藏官方原图标 */
.header-btn-video {
  background-image: url('https://img.heliar.top/file/1778027522636_retouch_2026050607325383.png') !important;
  background-repeat: no-repeat !important;

  /* ▼▼▼▼▼ 调整大小和位置的地方 ▼▼▼▼▼ */
  width: 36px !important;             /* 【整体触控区宽度】无需改动 */
  height: 36px !important;            /* 【整体触控区高度】无需改动 */
  background-size: 20px 22px !important; /* 【图标大小】前面是宽，后面是高 */
  background-position: center center !important; /* 【上下左右位置】center代表居中。如果是 "10px 5px" 就是距离左10px 距离上5px */
}

/* --- 设置按钮 --- */
.header-btn-info svg { display: none !important; } /* 隐藏官方原图标 */
.header-btn-info {
  background-image: url('https://img.heliar.top/file/1778027525979_retouch_2026050607345594.png') !important;
  background-repeat: no-repeat !important;

  /* ▼▼▼▼▼ 调整大小和位置的地方 ▼▼▼▼▼ */
  width: 36px !important;             /* 【整体触控区宽度】无需改动 */
  height: 36px !important;            /* 【整体触控区高度】无需改动 */
  background-size: 5px 20px !important; /* 【图标大小】前面是宽，后面是高 */
  background-position: center center !important; /* 【上下左右位置】控制图标在触控区内的位置 */
}

/* ================================================= */
/* 4. 顶栏右侧下边缘装饰贴图（带阴影） */
/* ================================================= */
.chat-header-custom {
  position: relative !important;
}
.chat-header-custom::after {
  content: "";
  position: absolute;
  background-image: url('https://img.heliar.top/file/1778027526373_retouch_2026050607425271.png');
  background-repeat: no-repeat;
  background-size: contain;
  pointer-events: none; /* 必须加！否则贴图凸出来的地方会挡住下方气泡的点击 */
  z-index: 10;          /* 保证贴图悬浮在最上层 */

  /* 【阴影效果】参数：X偏移 Y偏移 模糊程度 颜色 */
  filter: drop-shadow(0 4px 6px rgba(0, 0, 0, 0.15)); 

  /* ▼▼▼▼▼ 调整大小和位置的地方 ▼▼▼▼▼ */
  width: 90px;           /* 【大小】图片的宽度 */
  height: 90px;          /* 【大小】图片的高度 */
  bottom: -85px;         /* 【上下位置】负值表示超出顶栏底线，往下掉出 25px */
  right: 15px;           /* 【左右位置】距离屏幕最右侧的距离，数字越大越靠左 */
}
/* 彻底去除顶栏的所有系统边框和阴影 */
.chat-header-custom,
.glass-header {
  border-bottom: none !important;
  box-shadow: none !important;
  filter: none !important; /* 防止有些主题用 filter 渲染阴影 */
}
/* ================================================= */
/* ---------- 底栏完整定制 (全透明 + 黄金比例 30px) --------- */
/* ================================================= */

:root {
  /* 1. 取消底栏大背景和顶部分隔线 */
  --input-area-bg: transparent;          
  --input-area-border-top: transparent;  

  /* 【整体沉底位置】上 右 下 左。修改第三个数值(8px)可调整底栏距离屏幕底部的距离 */
  --input-area-padding: 0px 16px 8px 16px; 

  /* 破除系统锁定的默认最低高度 */
  --input-area-min-height: 30px; 
}

/* 彻底清除底栏毛玻璃和阴影 */
.input-area-custom {
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: none !important;
}
/* 必须要有这行作为绝对定位的基准！ */
.input-row-wrapper {
  position: relative !important;
}

/* ================================================= */
/* ---------- 胶囊输入框本体 (圆形 + 30px 纤薄) ----------- */
/* ================================================= */
.input-action-bar-custom {
  background: #F1F5F8 !important;     /* 胶囊背景颜色改为淡蓝灰色 */
  border-radius: 30px !important;     

  /* ▼▼▼ 胶囊高度 ▼▼▼ */
  min-height: 35px !important;        
  height: 35px !important;            

  margin-left: 0 !important;          
  padding-left: 34px !important;      
  margin-right: 42px !important;      
}

/* ================================================= */
/* --------- 加号按钮 (塞入胶囊左内侧 + 隐身) --------- */
/* ================================================= */

.input-btn-plus {
  position: absolute !important;
  z-index: 10 !important;
  opacity: 0 !important;              /* 【隐身状态】0 为完全透明，但依然可以点击！ */

  /* ▼▼▼ 调整位置和大小 ▼▼▼ */
  left: 6px !important;               /* 贴在胶囊最左侧内部 */
  bottom: 0px !important;             /* 完美贴底 */
  width: 30px !important;             /* 触控区宽度 */
  height: 30px !important;            /* 【必须与胶囊同高】才不会撑爆胶囊 */
}

/* ================================================= */
/* ------- 语音与表情按钮 (留在胶囊右内侧 + 隐身) ------ */
/* ================================================= */

.input-btn-mic,
.input-btn-sticker {
  opacity: 0 !important;              /* 【隐身状态】0 为完全透明，依然可以点击！ */
  width: 28px !important;             /* 保留足够的手指触控宽度 */
}

/* 同步所有内部按键的高度，防止骨架撑破外面的胶囊皮肤 */
.input-btn-mic,
.input-btn-sticker,
.send-btn-custom {
  height: 30px !important;            
  min-height: 30px !important;
}

/* ================================================= */
/* -------- AI 按钮 (移出胶囊右外侧 + 替换贴图) ------- */
/* ================================================= */

.input-btn-ai svg { display: none !important; }  /* 彻底隐藏官方原始的图标 */

.input-btn-ai {
  position: absolute !important;
  z-index: 10 !important;
  opacity: 1 !important;              /* 确保贴图可见 */
  background-image: url('https://img.heliar.top/file/1778027527064_retouch_2026050607435715.png') !important;
  background-repeat: no-repeat !important;

  /* ▼▼▼ 调整位置和大小 ▼▼▼ */
  right: 0 !important;                /* 【左右位置】强制贴在屏幕最右侧（胶囊外面） */
  bottom: -3px !important;            /* 【上下位置】胶囊30px，AI按钮36px，下沉3px刚好完美居中对齐！ */
  width: 36px !important;             /* 【整体触控区宽度】 */
  height: 36px !important;            /* 【整体触控区高度】 */
  background-size: 26px 26px !important;  /* 【贴图图标大小】前面是宽，后面是高 */
  background-position: center !important; /* 贴图在触控区内绝对居中 */
}

